/bin/bash -lc 'tmpdir="$(find "$TMPDIR" -maxdepth 1 -type d -name '"'gsvm-discovery.*' | tail -1)\"
python3 - \""'$tmpdir/page_1.html" <<'"'PY'
from bs4 import BeautifulSoup
import sys
s=BeautifulSoup(open(sys.argv[1], encoding='utf-8', errors='replace'), 'html.parser')
for i,t in enumerate(s.find_all('table'),1):
 print(f'-- table {i} --')
 for tr in t.find_all('tr'):
  cells=[' '.join(c.get_text(' ', strip=True).split()) for c in tr.find_all(['th','td'])]
  if cells: print(' | '.join(cells))
for i,el in enumerate(s.find_all(['h1','h2','h3','h4','h5']),1):
 txt=' '.join(el.get_text(' ', strip=True).split())
 if txt: print(f'heading {i}: {txt}')
PY"

